class Check(HTMLParser):
 def __init__(self):super().__init__();self.stack=[];self.script=False
 def handle_starttag(self,tag,attrs):
  if tag in ['sc-if','sc-for','div','button','span']:self.stack.append(tag)
  if tag=='script' and 'data-dc-script' in dict(attrs):self.script=True
 def handle_endtag(self,tag):
  if tag in ['sc-if','sc-for','div','button','span']:assert self.stack and self.stack.pop()==tag,tag
